package geo

import (
	"testing"
)

func TestSpec_Dist(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name string
		a, b Point
		want float64
	}{
		{"same point", Point{0, 0}, Point{0, 0}, 0},
		{"horizontal", Point{0, 0}, Point{3, 0}, 3},
		{"3-4-5 triangle", Point{0, 0}, Point{3, 4}, 5},
	}

	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()

			got := Dist(c.a, c.b)
			if got != c.want {
				t.Errorf("Dist(%v, %v) = %v, want %v", c.a, c.b, got, c.want)
			}
		})
	}
}

